"""
TIE-BREAK CHANGE ONLY (one change, encoder only).

Problem: with 32 channels, the majority vote is exactly 16 vs 16 in about 14% of bits.
The original encoder sends those bits to 0, which biases every frame toward 0.

Fix: at a tie, the bit is taken from a fixed random vector Z.
Z is one Bernoulli(0.5) draw per bit position, made once from a seed.
It is fixed, not redrawn per frame, so the same frame always encodes to the same vector.

Everything else is inherited unchanged: IDs, levels, XOR binding, the prototype rule
(perceptron-style), and predict_proba.
"""
import numpy as np
from tabular_hdc_perceptron import TabularHDCPerceptron


class TabularHDCPerceptronTieBreak(TabularHDCPerceptron):
    def __init__(self, *args, encode_tie_seed=123, **kwargs):
        super().__init__(*args, **kwargs)
        rng = np.random.default_rng(encode_tie_seed)
        self.Z = rng.integers(0, 2, size=self.D, dtype=np.uint8)   # fixed coin flips, Bernoulli(0.5)

    def encode_row(self, level_indices_row):
        level_vectors = self.CIM[level_indices_row]
        bound = np.bitwise_xor(self.feature_IM, level_vectors)
        summed = np.sum(bound, axis=0)
        half = self.num_features / 2
        out = (summed > half).astype(np.uint8)
        ties = summed == half
        out[ties] = self.Z[ties]
        return out